/* Colour 0.4.7 rendering adapter, delivered as a static JavaScript asset. */
self.LIGHTING_PYTHON_SOURCE = "\"\"\"Spectral color quality calculations using Colour 0.4.7 (BSD-3-Clause).\nMethod editions are explicit; results are research calculations, not certification.\n\"\"\"\nimport json\nimport warnings\nimport numpy as np\nimport colour\nfrom colour.temperature import uv_to_CCT_Robertson1968, CCT_to_xy_CIE_D\nwarnings.filterwarnings('ignore', category=colour.utilities.ColourUsageWarning)\n\ndef calculate(payload):\n    points = np.asarray(payload['points'], dtype=float)\n    waves = np.arange(360, 831, 1, dtype=float)\n    values = np.interp(waves, points[:, 0], points[:, 1], left=0, right=0)\n    sd = colour.SpectralDistribution(dict(zip(waves, values)), name='Uploaded / selected spectrum')\n    tm = colour.colour_fidelity_index(sd, additional_data=True, method='ANSI/IES TM-30-18')\n    if not (2000 <= tm.CCT <= 25000) or abs(tm.D_uv) > .05:\n        raise ValueError('Color rendition is reported here only for near-white spectra: CCT 2000\u201325000 K and |Duv| \u2264 0.05.')\n    cri = colour.colour_rendering_index(sd, additional_data=True, method='CIE 2024')\n    cqs = colour.colour_quality_scale(sd, additional_data=True, method='NIST CQS 9.0')\n    cmfs = colour.MSDS_CMFS['CIE 1931 2 Degree Standard Observer']\n    uv = colour.UCS_to_uv(colour.XYZ_to_UCS(colour.sd_to_XYZ(sd, cmfs)))\n    cct = float(uv_to_CCT_Robertson1968(uv)[0])\n    ref = colour.sd_blackbody(cct, sd.shape) if cct < 5000 else colour.sd_CIE_illuminant_D_series(CCT_to_xy_CIE_D(cct)).align(sd.shape)\n    uv_ref = colour.UCS_to_uv(colour.XYZ_to_UCS(colour.sd_to_XYZ(ref, cmfs)))\n    cri_distance = float(np.linalg.norm(uv-uv_ref))\n    cri_valid = cri_distance <= .0054\n    # TM-30 uses its prescribed 10\u00b0 observer for sample colorimetry; CCT uses 2\u00b0.\n    return {\n        'versions': {'colour': colour.__version__, 'CRI': 'CIE 2024 / 15 samples', 'CQS': 'NIST CQS 9.0', 'TM30': 'ANSI/IES TM-30-18'},\n        'cri': {'ra': float(cri.Q_a), 'samples': {str(k): float(v.Q_a) for k,v in cri.Q_as.items()}, 'valid': bool(cri_valid), 'reference_distance': cri_distance},\n        'cqs': {'qa': float(cqs.Q_a), 'qf': float(cqs.Q_f), 'qg': float(cqs.Q_g)},\n        'tm30': {'rf': float(tm.R_f), 'rg': float(tm.R_g), 'cct': float(tm.CCT), 'duv': float(tm.D_uv),\n                 'sample_rf': np.asarray(tm.R_s).tolist(), 'hue_rf': np.asarray(tm.R_fs).tolist(),\n                 'chroma_shift': np.asarray(tm.R_cs).tolist(), 'hue_shift_percent': (100*np.asarray(tm.R_hs)).tolist(),\n                 'test': (np.asarray(tm.averages_test)/np.asarray(tm.average_norms)[:,None]*100).tolist(),\n                 'reference': (np.asarray(tm.averages_reference)/np.asarray(tm.average_norms)[:,None]*100).tolist()},\n        'assumed_zero': bool(payload.get('zero', False)),\n    }\n";
